<div class="admin-heading"><div><h1>Documents</h1><p>Find, organize, and share the resources your team needs.</p></div><div class="admin-actions"><a class="admin-btn primary" href="#">Upload document</a></div></div><div class="metric-grid"><div class="metric-card"><small>All documents</small><strong><?= count($documents) ?></strong><span>Across team folders</span></div><div class="metric-card"><small>Published</small><strong><?= count(array_filter($documents,fn($d)=>$d['status']==='published')) ?></strong><span>Available to your team</span></div><div class="metric-card"><small>Drafts</small><strong><?= count(array_filter($documents,fn($d)=>$d['status']==='draft')) ?></strong><span>Only visible to owners</span></div><div class="metric-card"><small>In review</small><strong><?= count(array_filter($documents,fn($d)=>$d['status']==='in_review')) ?></strong><span>Awaiting approval</span></div></div><section class="admin-panel data-panel"><div class="table-toolbar"><input placeholder="Search by document name or owner"><select><option>All types</option></select><select><option>Newest first</option></select></div><table class="admin-table"><thead><tr><th>Document name</th><th>Category</th><th>Updated</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($documents as $document): ?><tr><td><?= htmlspecialchars($document['name']) ?></td><td><?= htmlspecialchars($document['category']) ?></td><td><?= date('d M Y',strtotime($document['created_at'])) ?></td><td><span class="badge"><?= htmlspecialchars($document['status']) ?></span></td><td><a class="admin-btn" href="#">Open</a></td></tr><?php endforeach; ?></tbody></table><div class="table-note">Showing <?= count($documents) ?> documents from backup_mentora_db.</div></section><?php require __DIR__.'/../includes/admin_footer.php'; ?>